mkdir -p /tmp/pushgate-check && cat > /tmp/pushgate-check/check.mjs <<'EOF'
import assert from 'node:assert/strict';
import { createPushGate } from '<HOME>/Desktop/Open-Source/projelerim/proactive-gate/bench/head-to-head/results/round5-heldout-haiku/work/baseline-g2-2/bot.mjs';

// Tokyo is UTC+9 with no DST. Build instants from local Tokyo wall-clock time.
const tokyo = (iso) => new Date(`${iso}+09:00`);
const base = { id: 'u_8841', timeZone: 'Asia/Tokyo', quietStart: '00:00', quietEnd: '00:00', dailyCap: 3 };
const ok = { allowed: true, reason: null };
const no = (reason) => ({ allowed: false, reason });
let n = 0;
const t = (name, fn) => { fn(); n++; console.log('ok -', name); };

t('first push allowed, returns null reason', () => {
  const g = createPushGate();
  assert.deepEqual(g.attempt(base, tokyo('2026-10-22T12:00:00')), ok);
});

t('min gap: 59 min blocked as too_soon, 60 min allowed', () => {
  const g = createPushGate();
  g.attempt(base, tokyo('2026-10-22T12:00:00'));
  assert.deepEqual(g.attempt(base, tokyo('2026-10-22T12:59:00')), no('too_soon'));
  assert.deepEqual(g.attempt(base, tokyo('2026-10-22T13:00:00')), ok);
});

t('daily cap: 3 allowed then daily_cap_reached', () => {
  const g = createPushGate();
  assert.deepEqual(g.attempt(base, tokyo('2026-10-22T09:00:00')), ok);
  assert.deepEqual(g.attempt(base, tokyo('2026-10-22T11:00:00')), ok);
  assert.deepEqual(g.attempt(base, tokyo('2026-10-22T13:00:00')), ok);
  assert.deepEqual(g.attempt(base, tokyo('2026-10-22T15:00:00')), no('daily_cap_reached'));
});

t('daily cap resets at local midnight, not 24h after first push', () => {
  const g = createPushGate();
  g.attempt(base, tokyo('2026-10-22T20:00:00'));
  g.attempt(base, tokyo('2026-10-22T21:00:00'));
  g.attempt(base, tokyo('2026-10-22T22:00:00'));
  assert.deepEqual(g.attempt(base, tokyo('2026-10-22T23:30:00')), no('daily_cap_reached'));
  assert.deepEqual(g.attempt(base, tokyo('2026-10-23T00:30:00')), ok);
});

t('dailyCap 0 blocks everything with daily_cap_reached', () => {
  const g = createPushGate();
  assert.deepEqual(g.attempt({ ...base, dailyCap: 0 }, tokyo('2026-10-22T12:00:00')), no('daily_cap_reached'));
});

t('quiet hours wrap past midnight: 22:00-07:00', () => {
  const u = { ...base, quietStart: '22:00', quietEnd: '07:00', dailyCap: 99 };
  const g = createPushGate();
  assert.deepEqual(g.attempt(u, tokyo('2026-10-22T21:59:00')), ok);
  assert.deepEqual(g.attempt(u, tokyo('2026-10-22T22:00:00')), no('quiet_hours'));
  assert.deepEqual(g.attempt(u, tokyo('2026-10-23T00:30:00')), no('quiet_hours'));
  assert.deepEqual(g.attempt(u, tokyo('2026-10-23T06:59:00')), no('quiet_hours'));
  assert.deepEqual(g.attempt(u, tokyo('2026-10-23T07:00:00')), ok);
});

t('quiet hours not wrapping: 13:00-14:00', () => {
  const u = { ...base, quietStart: '13:00', quietEnd: '14:00', dailyCap: 99 };
  const g = createPushGate();
  assert.deepEqual(g.attempt(u, tokyo('2026-10-22T12:59:00')), ok);
  assert.deepEqual(g.attempt(u, tokyo('2026-10-22T13:30:00')), no('quiet_hours'));
  assert.deepEqual(g.attempt(u, tokyo('2026-10-22T14:00:00')), ok);
});

t('quiet hours use the user zone, not UTC or server time', () => {
  // 2026-10-22T16:00Z is 01:00 in Tokyo (quiet) and 12:00 in New York (not quiet).
  const at = new Date('2026-10-22T16:00:00Z');
  const g1 = createPushGate();
  assert.deepEqual(g1.attempt({ ...base, quietStart: '22:00', quietEnd: '07:00' }, at), no('quiet_hours'));
  const g2 = createPushGate();
  assert.deepEqual(g2.attempt({ ...base, id: 'u_ny', timeZone: 'America/New_York', quietStart: '22:00', quietEnd: '07:00' }, at), ok);
});

t('blocked attempts are not counted toward cap or gap', () => {
  const u = { ...base, quietStart: '22:00', quietEnd: '07:00', dailyCap: 1 };
  const g = createPushGate();
  assert.deepEqual(g.attempt(u, tokyo('2026-10-22T23:00:00')), no('quiet_hours'));
  assert.deepEqual(g.attempt(u, tokyo('2026-10-23T07:00:00')), ok);
  assert.deepEqual(g.attempt(u, tokyo('2026-10-23T08:00:00')), no('daily_cap_reached'));
});

t('users are isolated; gates are independent', () => {
  const g = createPushGate();
  assert.deepEqual(g.attempt(base, tokyo('2026-10-22T12:00:00')), ok);
  assert.deepEqual(g.attempt({ ...base, id: 'u_2' }, tokyo('2026-10-22T12:00:00')), ok);
  assert.deepEqual(createPushGate().attempt(base, tokyo('2026-10-22T12:10:00')), ok);
});

t('per-call settings are used: cap raised mid-day', () => {
  const g = createPushGate();
  g.attempt({ ...base, dailyCap: 1 }, tokyo('2026-10-22T09:00:00'));
  assert.deepEqual(g.attempt({ ...base, dailyCap: 1 }, tokyo('2026-10-22T11:00:00')), no('daily_cap_reached'));
  assert.deepEqual(g.attempt({ ...base, dailyCap: 2 }, tokyo('2026-10-22T11:00:00')), ok);
});

t('DST: New York day boundary on spring-forward day still caps per local day', () => {
  const ny = { ...base, id: 'u_ny', timeZone: 'America/New_York', dailyCap: 2 };
  const g = createPushGate();
  assert.deepEqual(g.attempt(ny, new Date('2026-03-08T12:00:00-04:00')), ok);
  assert.deepEqual(g.attempt(ny, new Date('2026-03-08T14:00:00-04:00')), ok);
  assert.deepEqual(g.attempt(ny, new Date('2026-03-08T18:00:00-04:00')), no('daily_cap_reached'));
  assert.deepEqual(g.attempt(ny, new Date('2026-03-09T09:00:00-04:00')), ok);
});

t('invalid input throws TypeError / RangeError', () => {
  const g = createPushGate();
  const now = tokyo('2026-10-22T12:00:00');
  assert.throws(() => g.attempt({ ...base, quietStart: '7:00' }, now), TypeError);
  assert.throws(() => g.attempt({ ...base, dailyCap: -1 }, now), TypeError);
  assert.throws(() => g.attempt({ ...base, dailyCap: 2.5 }, now), TypeError);
  assert.throws(() => g.attempt(base, new Date('nope')), TypeError);
  assert.throws(() => g.attempt({ ...base, timeZone: 'Mars/Olympus' }, now), RangeError);
});

console.log(`\n${n} tests passed`);
EOF
cd /tmp/pushgate-check && node check.mjs
